        let mut at = self.root;
        while at != NONE {
            if *key == self.nodes[at as usize].key {
                return Some(&mut self.nodes[at as usize].weight);
            }
            at = if *key < self.nodes[at as usize].key {
                self.nodes[at as usize].left
